"use client"

import * as React from "react"
import { Sheet } from "scrollsheet"

import { cn } from "@/lib/utils"

function Dialog({ ...props }: React.ComponentProps<typeof Sheet.Root>) {
  return <Sheet.Root data-slot="dialog" side="center" {...props} />
}

function DialogTrigger({
  ...props
}: React.ComponentProps<typeof Sheet.Trigger>) {
  return <Sheet.Trigger data-slot="dialog-trigger" {...props} />
}

function DialogContent({
  className,
  children,
  ...props
}: React.ComponentProps<typeof Sheet.Content>) {
  return (
    <Sheet.Content
      data-slot="dialog-content"
      className={cn("bg-background w-full max-w-lg rounded-lg border p-6 shadow-lg", className)}
      {...props}
    >
      {children}
    </Sheet.Content>
  )
}

function DialogHeader({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="dialog-header"
      className={cn("flex flex-col gap-2 text-center sm:text-left", className)}
      {...props}
    />
  )
}

function DialogFooter({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="dialog-footer"
      className={cn("flex flex-col-reverse gap-2 sm:flex-row sm:justify-end", className)}
      {...props}
    />
  )
}

function DialogTitle({
  className,
  ...props
}: React.ComponentProps<typeof Sheet.Title>) {
  return (
    <Sheet.Title
      data-slot="dialog-title"
      className={cn("text-foreground text-lg font-semibold", className)}
      {...props}
    />
  )
}

function DialogDescription({
  className,
  ...props
}: React.ComponentProps<typeof Sheet.Description>) {
  return (
    <Sheet.Description
      data-slot="dialog-description"
      className={cn("text-muted-foreground text-sm", className)}
      {...props}
    />
  )
}

function DialogClose({
  className,
  ...props
}: React.ComponentProps<typeof Sheet.Close>) {
  return (
    <Sheet.Close
      data-slot="dialog-close"
      className={cn(
        "text-foreground/70 hover:text-foreground absolute top-4 right-4 text-sm underline-offset-4 hover:underline",
        className
      )}
      {...props}
    />
  )
}

export {
  Dialog,
  DialogTrigger,
  DialogContent,
  DialogHeader,
  DialogFooter,
  DialogTitle,
  DialogDescription,
  DialogClose,
}
